function startGameOfLife(canvasId) {
    const canvas = document.getElementById(canvasId);
    canvas.width = 500; canvas.height = 500;
    const ctx = canvas.getContext('2d');
    const cellsX = 50, cellsY = 50, cellSize = 10;
    const emojiAge = [
        ['🌱', '🌱'], // ages 0-1
        ['🌿', '🌿'], // 2-4
        ['🌳', '🌳']  // 5+
    ];
    const fadeDuration = 30; // frames
    let grid = [];
    let fadeQueue = [];
    let genPerSecond = 5;
    let lastGen = 0;
    const speedSlider = document.createElement('input'); speedSlider.type='range'; speedSlider.min=1; speedSlider.max=10; speedSlider.value=genPerSecond; speedSlider.style.position='absolute'; speedSlider.style.top='520px';
    const speedLabel = document.createElement('span'); speedLabel.textContent=` Speed: ${genPerSecond} gen/s`;
    const patternSelect = document.createElement('select'); patternSelect.style.position='absolute'; patternSelect.style.top='540px';
    ['Glider','Blinker','Gosper Gun','Pulsar'].forEach(p=>{let opt=document.createElement('option');opt.value=p;opt.text=p;patternSelect.appendChild(opt);});
    const randomBtn = document.createElement('button'); randomBtn.textContent='Randomize'; randomBtn.style.position='absolute'; randomBtn.style.top='560px';
    const clearBtn = document.createElement('button'); clearBtn.textContent='Clear'; clearBtn.style.position='absolute'; clearBtn.style.top='560px';
    document.body.appendChild(speedSlider); document.body.appendChild(speedLabel); document.body.appendChild(patternSelect); document.body.appendChild(randomBtn); document.body.appendChild(clearBtn);
    function initGrid() { for(let y=0;y<cellsY;y++){grid[y]=[];for(let x=0;x<cellsX;x++){grid[y][x]={alive:false,age:0};}}}
    function clearGrid(){initGrid();fadeQueue=[];}
    const patterns = {
        'Glider':[[1,0],[2,1],[0,2],[1,2],[2,2]],
        'Blinker':[[0,1],[1,1],[2,1]],
        'Pulsar':[
            [3,0],[4,0],[5,0],[0,3],[1,3],[2,3],[0,4],[1,4],[2,4],[0,5],[1,5],[2,5],[3,10],[4,10],[5,10],
            [9,0],[10,0],[11,0],[9,3],[11,3],[9,4],[11,4],[9,5],[11,5],[9,6],[10,6],[11,6],[9,9],[10,9],[11,9],
            [3,12],[4,12],[5,12],[0,9],[1,9],[2,9],[0,10],[1,10],[2,10],[0,11],[1,11],[2,11],[0,12],[1,12],[2,12]
        ],
        'Gosper Gun':[
            [36, 24],[36, 25],[37, 24],[37, 25],[38, 24],[38, 25],[31, 16],[31, 17],[33, 16],[33, 17],[4, 0],[5, 0],[2, 1],[6, 1],[1, 2],[7, 2],[3, 3],[4, 3],[5, 3],[6, 3],[2, 4],[7, 4],[2, 5],[3, 5],[6, 5],[7, 5],[1, 6],[2, 6],[5, 6],[6, 6],[3, 8],[4, 8],[5, 8],[3, 9],[4, 9],[5, 9],[5, 0],[14, 0],[14, 1],[13, 1],[12, 2],[16, 2],[12, 3],[12, 4],[13, 4],[14, 4],[14, 5],[16, 5],[2, 3],[13, 3],[14, 3],[12, 21],[13, 20],[14] ]
    };
    function loadPattern(name) {
        clearGrid(); fadeQueue=[];
        const pattern = patterns[name];
        const offsetX = Math.floor((cellsX - 15)/2);
        const offsetY = Math.floor((cellsY - 10)/2);
        pattern.forEach(([dx,dy])=>{
            let x=dx+offsetX,y=dy+offsetY;
            if(x>=0&&x<cellsX&&y>=0&&y<cellsY){grid[y][x]={alive:true,age:1};}
        });
    }
    speedSlider.oninput=function(){genPerSecond=parseInt(this.value); speedLabel.textContent=` Speed: ${genPerSecond} gen/s`;}
    patternSelect.onchange=function(){loadPattern(this.value);}
    randomBtn.onclick=function(){
        for(let y=0;y<cellsY;y++)for(let x=0;x<cellsX;x++){grid[y][x].alive=Math.random()<0.3;grid[y][x].age=grid[y][x].alive?1:0;}
        fadeQueue=[];
    };
    clearBtn.onclick=function(){clearGrid();}
    canvas.addEventListener('click',function(e){let rect=canvas.getBoundingClientRect();let x=Math.floor((e.clientX-rect.left)/cellSize);let y=Math.floor((e.clientY-rect.top)/cellSize);if(x>=0&&x<cellsX&&y>=0&&y<cellsY){if(grid[y][x].alive){grid[y][x].alive=false;grid[y][x].age=0;fadeQueue.push({x,y,remain:fadeDuration});}else{grid[y][x].alive=true;grid[y][x].age=1;fadeQueue=fadeQueue.filter(f=>!(f.x===x&&f.y===y));}}});
    function draw(){
        ctx.clearRect(0,0,canvas.width,canvas.height);
        ctx.textAlign='center';ctx.textBaseline='middle';
        const emojiSize=cellSize-2;
        ctx.font=`${emojiSize}px serif`;
        for(let y=0;y<cellsY;y++)for(let x=0;x<cellsX;x++){
            let cell=grid[y][x];
            if(cell.alive){
                let emoji=emojiAge[Math.min(2,Math.floor((cell.age-1)/3))][0];
                ctx.fillText(emoji,(x+0.5)*cellSize,(y+0.5)*cellSize);
            }
        }
        fadeQueue.forEach(v=>{let alpha=v.remain/fadeDuration;ctx.globalAlpha=alpha;let emoji=emojiAge[0][0];ctx.fillText(emoji,(v.x+0.5)*cellSize,(v.y+0.5)*cellSize);});
        ctx.globalAlpha=1;
    }
    function nextGeneration(){
        const newGrid=JSON.parse(JSON.stringify(grid));
        for(let y=0;y<cellsY;y++)for(let x=0;x<cellsX;x++){
            let liveNeighbors=0;
            for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){
                if(dx===0&&dy===0)continue;
                let nx=x+dx,ny=y+dy;
                if(nx>=0&&nx<cellsX&&ny>=0&&ny<cellsY&&grid[ny][nx].alive)liveNeighbors++;
            }
            if(grid[y][x].alive){
                if(liveNeighbors<2||liveNeighbors>3){newGrid[y][x].alive=false;newGrid[y][x].age=0;fadeQueue.push({x,y,remain:fadeDuration});}
                else{newGrid[y][x].age++;}
            }else{
                if(liveNeighbors===3){newGrid[y][x].alive=true;newGrid[y][x].age=1;}
            }
        }
        grid=newGrid;
    }
    function step(timestamp){
        if(timestamp-lastGen>=1000/genPerSecond){nextGeneration();lastGen=timestamp;}
        fadeQueue.forEach(f=>f.remain--);
        fadeQueue=fadeQueue.filter(f=>f.remain>0);
        draw();
        requestAnimationFrame(step);
    }
    initGrid();
    requestAnimationFrame(step);
}
